"use client";

import { useCallback, useId, useState } from "react";
import { usePathname, useRouter } from "next/navigation";
import type { SupportProgram } from "@/src/data/programs";
import { Button, Switch, ToastProvider, cn, useToast } from "@/src/components/ui";
import { ProgramCard } from "@/src/components/domain";
import { LeaveDialog } from "./LeaveDialog";
import { getProgramTags } from "../_lib/program-tags";

export interface ProgramsExplorerProps {
  programs: SupportProgram[];
  /** Tag pre-selected from the `?tag=` query string on first load, if any. */
  initialTag: string | null;
}

const TAG_BUTTON_BASE =
  "inline-flex items-center rounded-[var(--radius-pill)] border px-[var(--space-3)] py-[var(--space-1)] text-[length:var(--text-caption-size)] font-[var(--weight-medium)] transition-colors duration-[var(--dur-fast)] ease-[var(--ease-standard)]";

/**
 * `ToastProvider` must wrap this subtree since the root layout is off-limits
 * to this task — mounting it here keeps the toast scoped to the Programs
 * route without touching any shared file.
 */
export function ProgramsExplorer(props: ProgramsExplorerProps) {
  return (
    <ToastProvider>
      <ProgramsExplorerInner {...props} />
    </ToastProvider>
  );
}

function ProgramsExplorerInner({ programs, initialTag }: ProgramsExplorerProps) {
  const router = useRouter();
  const pathname = usePathname();
  const toast = useToast();
  const notifyDescriptionId = useId();

  const tags = getProgramTags(programs);
  const [activeTag, setActiveTag] = useState<string | null>(
    initialTag && tags.includes(initialTag) ? initialTag : null,
  );
  const [notifyEnabled, setNotifyEnabled] = useState(false);
  const [leaveTarget, setLeaveTarget] = useState<SupportProgram | null>(null);

  const selectTag = useCallback(
    (tag: string | null) => {
      setActiveTag(tag);
      const query = tag ? `?tag=${encodeURIComponent(tag)}` : "";
      // {scroll:false} keeps the list in place — this is a client-side
      // filter, not a navigation, so the viewport shouldn't jump.
      router.replace(`${pathname}${query}`, { scroll: false });
    },
    [pathname, router],
  );

  const handleNotifyChange = useCallback(
    (checked: boolean) => {
      setNotifyEnabled(checked);
      toast.show({
        title: checked ? "신규 지원사업 알림을 켰어요" : "신규 지원사업 알림을 껐어요",
        description: checked
          ? "새로운 지원사업이 등록되면 알려드릴게요."
          : "필요할 때 다시 켤 수 있어요.",
        tone: checked ? "good" : "neutral",
      });
    },
    [toast],
  );

  const filteredPrograms = activeTag
    ? programs.filter((program) => program.tags.includes(activeTag))
    : programs;

  return (
    <div className="flex flex-col gap-[var(--space-6)]">
      <div className="flex flex-col gap-[var(--space-4)] rounded-[var(--radius-lg)] border border-[var(--border-subtle)] bg-[var(--surface-sunken)] p-[var(--pad-card)] sm:flex-row sm:items-center sm:justify-between">
        <div
          role="group"
          aria-label="지원사업 태그로 필터링"
          className="flex flex-wrap items-center gap-[var(--space-2)]"
        >
          <button
            type="button"
            aria-pressed={activeTag === null}
            onClick={() => selectTag(null)}
            className={cn(
              TAG_BUTTON_BASE,
              activeTag === null
                ? "border-[var(--action-primary)] bg-[var(--action-primary)] text-[var(--text-on-primary)]"
                : "border-[var(--border-subtle)] bg-[var(--surface-card)] text-[var(--text-body)] hover:border-[var(--border-brand)]",
            )}
          >
            전체
          </button>
          {tags.map((tag) => {
            const isActive = activeTag === tag;
            return (
              <button
                key={tag}
                type="button"
                aria-pressed={isActive}
                onClick={() => selectTag(isActive ? null : tag)}
                className={cn(
                  TAG_BUTTON_BASE,
                  isActive
                    ? "border-[var(--action-primary)] bg-[var(--action-primary)] text-[var(--text-on-primary)]"
                    : "border-[var(--border-subtle)] bg-[var(--surface-card)] text-[var(--text-body)] hover:border-[var(--border-brand)]",
                )}
              >
                {tag}
              </button>
            );
          })}
        </div>

        <Switch
          label="신규 지원사업 알림"
          description="새 지원사업이 열리면 알려드려요"
          checked={notifyEnabled}
          onChange={(event) => handleNotifyChange(event.target.checked)}
          aria-describedby={notifyDescriptionId}
        />
      </div>

      <p aria-live="polite" className="text-[length:var(--text-caption-size)] text-[var(--text-muted)]">
        {activeTag ? `"${activeTag}" 태그` : "전체 지원사업"} · {filteredPrograms.length}건
      </p>

      {filteredPrograms.length === 0 ? (
        <p className="rounded-[var(--radius-lg)] border border-dashed border-[var(--border-subtle)] p-[var(--pad-card)] text-center text-[var(--text-body-size)] text-[var(--text-muted)]">
          이 태그에 해당하는 지원사업이 아직 없어요.
        </p>
      ) : (
        <ul className="grid gap-[var(--space-4)] sm:grid-cols-2">
          {filteredPrograms.map((program) => (
            <li key={program.id} className="flex flex-col gap-[var(--space-3)]">
              <ProgramCard program={program} />
              <Button type="button" variant="outline" onClick={() => setLeaveTarget(program)}>
                신청 페이지 바로가기
              </Button>
            </li>
          ))}
        </ul>
      )}

      <LeaveDialog program={leaveTarget} onClose={() => setLeaveTarget(null)} />
    </div>
  );
}
