"use client";

import { useEffect, useId, useRef, useState } from "react";
import Link from "next/link";
import type { NavCta, NavItem } from "./nav-types";

export interface MobileNavProps {
  items: NavItem[];
  cta?: NavCta;
}

/**
 * Accessible disclosure menu for narrow viewports: a toggle button that
 * expands a panel listing the same links `AppBar` renders in its desktop
 * nav. This is a Client Component because it needs open/close state plus
 * outside-click and Escape-key handling — everything else in `AppBar` stays
 * a Server Component.
 */
export function MobileNav({ items, cta }: MobileNavProps) {
  const [open, setOpen] = useState(false);
  const panelId = useId();
  const panelRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!open) return undefined;

    function onKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") {
        setOpen(false);
        buttonRef.current?.focus();
      }
    }

    function onPointerDown(event: PointerEvent) {
      const target = event.target as Node;
      if (panelRef.current && !panelRef.current.contains(target) && !buttonRef.current?.contains(target)) {
        setOpen(false);
      }
    }

    document.addEventListener("keydown", onKeyDown);
    document.addEventListener("pointerdown", onPointerDown);
    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.removeEventListener("pointerdown", onPointerDown);
    };
  }, [open]);

  return (
    <div className="md:hidden">
      <button
        ref={buttonRef}
        type="button"
        aria-expanded={open}
        aria-controls={panelId}
        onClick={() => setOpen((value) => !value)}
        className="flex h-11 w-11 items-center justify-center rounded-[var(--radius-md)] border border-[var(--border-subtle)] text-[var(--text-strong)] transition-colors duration-[var(--dur-fast)] hover:bg-[var(--surface-sunken)]"
      >
        <span className="sr-only">{open ? "메뉴 닫기" : "메뉴 열기"}</span>
        <svg
          aria-hidden="true"
          viewBox="0 0 24 24"
          className="h-5 w-5"
          fill="none"
          stroke="currentColor"
          strokeWidth={2}
          strokeLinecap="round"
        >
          {open ? <path d="M6 6l12 12M18 6L6 18" /> : <path d="M4 7h16M4 12h16M4 17h16" />}
        </svg>
      </button>

      <div
        id={panelId}
        ref={panelRef}
        hidden={!open}
        className="absolute inset-x-0 top-full border-b border-[var(--border-subtle)] bg-[var(--surface-card)] shadow-[var(--shadow-sheet)]"
      >
        <nav aria-label="모바일 메뉴" className="eco-container flex flex-col gap-[var(--space-1)] py-[var(--space-3)]">
          {items.map((item) => (
            <Link
              key={item.href}
              href={item.href}
              aria-current={item.active ? "page" : undefined}
              onClick={() => setOpen(false)}
              className="rounded-[var(--radius-sm)] px-[var(--space-4)] py-[var(--space-3)] text-[length:var(--text-label-size)] font-medium text-[var(--text-body)] hover:bg-[var(--surface-sunken)] aria-[current=page]:bg-[var(--surface-brand-soft)] aria-[current=page]:text-[var(--text-link)]"
            >
              {item.label}
            </Link>
          ))}
          {cta ? (
            <Link
              href={cta.href}
              onClick={() => setOpen(false)}
              className="mt-[var(--space-2)] inline-flex items-center justify-center rounded-[var(--radius-pill)] bg-[var(--action-primary)] px-[var(--space-5)] py-[var(--space-3)] text-[length:var(--text-label-size)] font-bold text-[var(--text-on-primary)] hover:bg-[var(--action-primary-hover)]"
            >
              {cta.label}
            </Link>
          ) : null}
        </nav>
      </div>
    </div>
  );
}
