import type { SupportProgram } from "@/src/data/programs";

/**
 * Every distinct tag across the given programs, in first-seen (fixture)
 * order. Deterministic and side-effect free — no data is changed, this just
 * derives a route-local filter vocabulary from the existing `tags` field.
 */
export function getProgramTags(programs: SupportProgram[]): string[] {
  const seen = new Set<string>();
  const tags: string[] = [];
  for (const program of programs) {
    for (const tag of program.tags) {
      if (!seen.has(tag)) {
        seen.add(tag);
        tags.push(tag);
      }
    }
  }
  return tags;
}
